def share_masters(apps, schema_editor):
    """Credit terms and parties become one list for the group of companies.

    Credit terms with the same name in several companies become one. Each
    party ledger gets a group party: parties with the same GSTIN, or else
    the same name, become one, keeping the first one's details and adding
    the others' addresses and contacts. The credit limit and the salesman
    move to the company's ledger."""
    CreditTerm = apps.get_model("core", "CreditTerm")
    Party = apps.get_model("core", "Party")
    Ledger = apps.get_model("core", "Ledger")

    keep = {}
    for term in CreditTerm.objects.order_by("pk"):
        key = term.name.strip().lower()
        if key in keep:
            Party.objects.filter(credit_term=term).update(credit_term=keep[key])
            term.delete()
        else:
            keep[key] = term

    by_gstin, by_name = {}, {}
    for party in Party.objects.order_by("pk"):
        ledger = Ledger.objects.get(pk=party.ledger_id)
        first = (by_gstin.get(party.gstin) if party.gstin else None) or by_name.get(
            ledger.name.strip().lower()
        )
        if first is None:
            party.name = ledger.name
            party.save(update_fields=["name"])
            first = party
            if party.gstin:
                by_gstin[party.gstin] = party
            by_name[ledger.name.strip().lower()] = party
        else:
            labels = {a.label.lower() for a in first.addresses.all()}
            for a in party.addresses.all():
                if a.label.lower() not in labels:
                    a.party = first
                    a.is_billing = a.is_shipping = False
                    a.save()
            names = {c.name.lower() for c in first.contacts.all()}
            for c in party.contacts.all():
                if c.name.lower() not in names:
                    c.party = first
                    c.is_primary = False
                    c.save()
        Ledger.objects.filter(pk=ledger.pk).update(
            party_id=first.pk,
            credit_limit=party.credit_limit,
            salesman_id=party.salesman_id,
        )
    linked = set(
        Ledger.objects.filter(party_id__isnull=False).values_list("party_id", flat=True)
    )
    Party.objects.exclude(pk__in=linked).delete()


